import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.test.util.ReflectionTestUtils;
class CashClosingDocumentServiceTest {
 UUID tenant=UUID.randomUUID(),company=UUID.randomUUID(),branch=UUID.randomUUID(),cash=UUID.randomUUID(),id=UUID.randomUUID(),uid=UUID.randomUUID();
 CierreCajaRepository closures=mock(CierreCajaRepository.class);DetalleCierreCajaRepository details=mock(DetalleCierreCajaRepository.class);ResumenMedioPagoCierreCajaRepository payments=mock(ResumenMedioPagoCierreCajaRepository.class);DatosEmpresaRepository data=mock(DatosEmpresaRepository.class);
 FinancialMovementRepository movements=mock(FinancialMovementRepository.class);
 CashClosingDocumentService service=new CashClosingDocumentService(closures,details,payments,data,movements);CierreCaja closure;SesionCaja session;Empresa business;Usuario cashier;List<DetalleCierreCaja> rows;
 static BigDecimal m(String s){return new BigDecimal(s);}
 @BeforeEach void fixture(){
  auth(tenant,company,true,Set.of(),Set.of("cierres_caja.ver","cierres_caja.imprimir"));session=mock(SesionCaja.class);when(session.getTenantId()).thenReturn(tenant);when(session.getEmpresaId()).thenReturn(company);when(session.getCajaId()).thenReturn(cash);when(session.getSucursalId()).thenReturn(branch);when(session.getId()).thenReturn(UUID.randomUUID());when(session.getMonedaId()).thenReturn(UUID.randomUUID());when(session.getCodigoVisible()).thenReturn("TURN-01");when(session.getAbiertoEn()).thenReturn(OffsetDateTime.parse("2026-11-02T12:00:00Z"));when(session.getAbiertoPor()).thenReturn(uid);when(session.getFondoInicial()).thenReturn(m("5000"));
  var c=mock(Caja.class);when(c.getNombre()).thenReturn("Caja histórica");when(session.getCaja()).thenReturn(c);var b=mock(Sucursal.class);when(b.getNombre()).thenReturn("Principal histórica");when(session.getSucursal()).thenReturn(b);var currency=mock(Moneda.class);when(currency.getCodigoIso()).thenReturn("DOP");when(session.getMoneda()).thenReturn(currency);cashier=mock(Usuario.class);when(cashier.getNombre()).thenReturn("Juan");when(cashier.getApellido()).thenReturn("Pérez");when(session.getUsuarioApertura()).thenReturn(cashier);
  business=mock(Empresa.class);when(business.getId()).thenReturn(company);when(business.getTenantId()).thenReturn(tenant);when(business.getNombre()).thenReturn("Empresa histórica");when(business.getIdentificacionFiscal()).thenReturn("124543678");when(business.getPaisCodigo()).thenReturn("DO");when(business.getZonaHoraria()).thenReturn("America/Santo_Domingo");
  closure=new CierreCaja(tenant,company,"CIE-000018",session,OffsetDateTime.parse("2026-11-02T22:35:00Z"),uid,"María Rodríguez",new CierreCaja.Resumen(m("18500"),BigDecimal.ZERO,m("1500"),m("750"),BigDecimal.ZERO,BigDecimal.ZERO,m("20000"),m("750")),m("24245"),"Diferencia detectada",UUID.randomUUID(),business);ReflectionTestUtils.setField(closure,"id",id);when(closures.findByIdAndTenantIdAndEmpresaId(id,tenant,company)).thenReturn(Optional.of(closure));
  var den=mock(DenominacionCaja.class);when(den.getId()).thenReturn(UUID.randomUUID());when(den.getValor()).thenReturn(m("2000"));when(den.getTipo()).thenReturn(TipoDenominacionCaja.BANKNOTE);var coin=mock(DenominacionCaja.class);when(coin.getId()).thenReturn(UUID.randomUUID());when(coin.getValor()).thenReturn(BigDecimal.ONE);when(coin.getTipo()).thenReturn(TipoDenominacionCaja.COIN);rows=List.of(new DetalleCierreCaja(tenant,company,id,den,12,1),new DetalleCierreCaja(tenant,company,id,coin,245,2));when(details.findAllByCierreIdAndTenantIdAndEmpresaIdOrderByOrdenAsc(id,tenant,company)).thenReturn(rows);
  when(payments.findAllByCierreIdAndTenantIdAndEmpresaIdOrderByOrdenAsc(id,tenant,company)).thenReturn(List.of(new ResumenMedioPagoCierreCaja(tenant,company,id,MedioPagoMovimiento.CASH,m("18500"),1),new ResumenMedioPagoCierreCaja(tenant,company,id,MedioPagoMovimiento.CARD,m("10250"),2)));
  var official=List.of(collection("cash","Efectivo","18500"),collection("card","Tarjeta empresarial","10250"),collection("bank","Transferencia","4500"));when(movements.formasPagoSesion(tenant,company,session.getId())).thenReturn(official);
  var info=mock(DatosEmpresa.class);when(info.getDireccion()).thenReturn("Dirección histórica");when(info.getTelefono()).thenReturn("8095551234");when(data.findByEmpresaId(company)).thenReturn(Optional.of(info));
 }
 FormaPagoSesionProjection collection(String code,String name,String amount){var p=mock(FormaPagoSesionProjection.class);when(p.getCodigo()).thenReturn(code);when(p.getNombre()).thenReturn(name);when(p.getImporte()).thenReturn(m(amount));return p;}
 void auth(UUID t,UUID e,boolean all,Set<UUID> branches,Set<String> permissions){var p=new TenantPrincipal(uid,t,e,null,"DEMO","María Rodríguez","maria","",true,all,branches,permissions);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,null,p.getAuthorities()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void snapshotPreservesConfirmedValuesAndConvertsHistoricalDates(){service.conservar(closure,session,business);var d=service.documento(closure);assertThat(d.openingDateTime()).isEqualTo(LocalDateTime.of(2026,11,2,8,0));assertThat(d.closingDateTime()).isEqualTo(LocalDateTime.of(2026,11,2,18,35));assertThat(d.cashier()).isEqualTo("Juan Pérez");assertThat(d.closedBy()).isEqualTo("María Rodríguez");assertThat(d.countedCash()).isEqualByComparingTo("24245");assertThat(d.expectedCash()).isEqualByComparingTo("24250");assertThat(d.difference()).isEqualByComparingTo("-5");assertThat(d.status()).isEqualTo(Status.FALTANTE);assertThat(d.denominations()).hasSize(2);assertThat(d.denominations().getFirst().amount()).isEqualByComparingTo("24000");assertThat(d.paymentMethods()).hasSize(2);assertThat(d.paymentTotal().label()).isEqualTo("TOTAL ENTRADAS");assertThat(d.paymentTotal().amount()).isEqualByComparingTo("28750");assertThat(d.salesSummary().getFirst().label()).isEqualTo("Ventas en efectivo");assertThat(d.netSales()).isNull();assertThat(d.operations()).isEmpty();assertThat(d.shiftNumber()).isEqualTo("TURN-01");assertThat(d.cashSummary().cashEntries()).isEqualByComparingTo("20000");assertThat(d.collectionMethods()).extracting(PaymentMethod::name).containsExactly("Efectivo","Tarjeta empresarial","Transferencia");assertThat(d.totalCollected()).isEqualByComparingTo("33250");}
 @Test void reprintUsesOnlyCapturedDataAfterCatalogOrUserChanges(){service.conservar(closure,session,business);byte[] before=service.generar(id).contenido();String json=closure.getDocumentoPos();when(business.getNombre()).thenReturn("Nueva empresa");when(business.getZonaHoraria()).thenReturn("Asia/Tokyo");when(cashier.getNombre()).thenReturn("Nuevo usuario");clearInvocations(details,payments,data,movements);assertThat(service.generar(id).contenido()).isEqualTo(before);assertThat(closure.getDocumentoPos()).isEqualTo(json);verifyNoInteractions(details,payments,data,movements);assertThatThrownBy(()->service.conservar(closure,session,business)).isInstanceOf(IllegalStateException.class);}
 @Test void legacyReadsScopedStoredRowsWithoutCurrentIdentity(){var d=service.documento(closure);assertThat(d.company().name()).isEqualTo("Empresa histórica");assertThat(d.company().address()).isNull();assertThat(d.company().countryCode()).isEqualTo("XX");assertThat(d.closingDateTime()).isEqualTo(LocalDateTime.of(2026,11,2,22,35));assertThat(d.denominations()).hasSize(2);verifyNoInteractions(data);assertThat(closure.getDocumentoPos()).isNull();assertThat(d.collectionMethods()).isNull();assertThat(d.totalCollected()).isNull();assertThat(d.shiftNumber()).isEqualTo("TURN-01");verifyNoInteractions(movements);}
 @Test void tenantCompanyBranchAndSessionAreValidated(){service.conservar(closure,session,business);auth(UUID.randomUUID(),company,true,Set.of(),Set.of());assertThatThrownBy(()->service.documento(closure)).isInstanceOf(RecursoNoEncontradoException.class);auth(tenant,UUID.randomUUID(),true,Set.of(),Set.of());assertThatThrownBy(()->service.documento(closure)).isInstanceOf(RecursoNoEncontradoException.class);auth(tenant,company,false,Set.of(UUID.randomUUID()),Set.of());assertThatThrownBy(()->service.cargar(id)).isInstanceOf(RecursoNoEncontradoException.class);auth(tenant,company,true,Set.of(),Set.of());when(session.getCajaId()).thenReturn(UUID.randomUUID());assertThatThrownBy(()->service.conservar(closure,session,business)).isInstanceOf(RecursoNoEncontradoException.class);}
 @Test void renderFailureCannotReopenSessionOrChangeClosing(){ReflectionTestUtils.setField(closure,"empresaNombre","Empresa \uD83D\uDE00");service.conservar(closure,session,business);String json=closure.getDocumentoPos();assertThatThrownBy(()->service.generar(id)).isInstanceOf(ReglaNegocioException.class);assertThat(closure.getDocumentoPos()).isEqualTo(json);assertThat(closure.getContado()).isEqualByComparingTo("24245");assertThat(closure.getResult()).isEqualTo(ResultadoRecuentoCaja.SHORTAGE);verify(session,never()).cerrar(any(),any(),any(),any(),any());verify(closures,never()).save(any());}
 @Test void corruptSnapshotNeverReconstructsFromNewCatalogs(){closure.conservarDocumentoPos("{}");assertThatThrownBy(()->service.generar(id)).isInstanceOf(ReglaNegocioException.class);verifyNoInteractions(details,payments,data,movements);assertThat(closure.getDocumentoPos()).isEqualTo("{}");}
 @Test void diagnosticMismatchDoesNotRepairFinancialValues(){
  var logger=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(CashClosingDocumentService.class);var appender=new ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent>();appender.start();logger.addAppender(appender);
  try{ReflectionTestUtils.setField(rows.getFirst(),"subtotal",BigDecimal.ONE);service.conservar(closure,session,business);var d=service.documento(closure);assertThat(d.countedCash()).isEqualByComparingTo("24245");assertThat(d.denominations().getFirst().amount()).isEqualByComparingTo(BigDecimal.ONE);assertThat(appender.list).anyMatch(e->e.getFormattedMessage().contains("event=CashClosingCountMismatch"));}finally{logger.detachAppender(appender);appender.stop();}
 }
 @Test void backendRequiresPrintAndReadPermissionBeforeLookup(){var factory=new org.springframework.aop.framework.ProxyFactory(service);factory.addAdvisor(org.springframework.security.authorization.method.AuthorizationManagerBeforeMethodInterceptor.preAuthorize());var proxy=(CashClosingDocumentService)factory.getProxy();for(var permissions:List.of(Set.of("cierres_caja.ver"),Set.of("cierres_caja.imprimir"))){auth(tenant,company,true,Set.of(),permissions);clearInvocations(closures);assertThatThrownBy(()->proxy.cargar(id)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);verifyNoInteractions(closures);}}
 @Test void originalJsonSchemaIsReadableWithoutQueryingCurrentCollections(){
  service.conservar(closure,session,business);var mapper=tools.jackson.databind.json.JsonMapper.builder().build();var fields=mapper.readValue(closure.getDocumentoPos(),java.util.Map.class);for(String key:List.of("shiftNumber","cashSummary","collectionMethods","totalCollected"))fields.remove(key);ReflectionTestUtils.setField(closure,"documentoPos",mapper.writeValueAsString(fields));clearInvocations(movements,details,payments,data);var d=service.documento(closure);assertThat(d.shiftNumber()).isEqualTo("TURN-01");assertThat(d.cashSummary().cashEntries()).isEqualByComparingTo("20000");assertThat(d.expectedCash()).isEqualByComparingTo("24250");assertThat(d.collectionMethods()).isNull();assertThat(d.totalCollected()).isNull();assertThat(d.paymentTotal().amount()).isEqualByComparingTo("28750");verifyNoInteractions(movements,details,payments,data);
 }
 @Test void cardsAndTransfersNeverChangeTheConfirmedCashExpectation(){service.conservar(closure,session,business);var d=service.documento(closure);assertThat(d.totalCollected()).isEqualByComparingTo("33250");assertThat(d.expectedCash()).isEqualByComparingTo("24250");assertThat(d.cashSummary().cashEntries()).isEqualByComparingTo("20000");assertThat(d.countedCash()).isEqualByComparingTo("24245");assertThat(d.difference()).isEqualByComparingTo("-5");verify(movements).formasPagoSesion(tenant,company,session.getId());verify(movements,never()).save(any());}

}
